/**
 * Step recorders for the interactive trace players.
 *
 * Every player's animation frames are generated by RUNNING THE REAL
 * ALGORITHM in code and recording an immutable snapshot at each event,
 * never hand-written. Step N is a pure function of the recording, so
 * step-back restores the state exactly.
 *
 * This module is pure TypeScript with no React imports on purpose: it is
 * directly unit-testable (scripts/test-players.mjs).
 */

import type { TreeGraphNode } from "./tree-graph";

/* ------------------------------------------------------------------ */
/* Shared tree model                                                    */
/* ------------------------------------------------------------------ */

export interface TNode {
  key: string;
  label?: string;
  left?: TNode;
  right?: TNode;
}

/* ------------------------------------------------------------------ */
/* (a) Depth-first traversals with a call stack                         */
/* ------------------------------------------------------------------ */

export type TraversalOrder = "pre" | "in" | "post";

export interface TraversalStep {
  /** Key of the node the algorithm is currently at (null = finished). */
  current: string | null;
  /** "call" = entering the node, "return" = leaving it, "done" = end. */
  phase: "call" | "return" | "done";
  /** Path of active frames from the root to the current node. */
  callStack: string[];
  /** Output sequence accumulated so far (the visit order). */
  output: string[];
  /** Human description for the aria-live status line. */
  desc: string;
}

const ORDER_LABEL: Record<TraversalOrder, string> = {
  pre: "pre-order (node first)",
  in: "in-order (node between)",
  post: "post-order (node last)",
};

/** Run a real recursive DFS and record a snapshot at every event. */
export function recordTraversal(
  root: TNode,
  order: TraversalOrder,
): TraversalStep[] {
  const steps: TraversalStep[] = [];
  const output: string[] = [];
  const stack: string[] = [];

  // initial (reset) state: untouched tree, empty stack and output
  steps.push({
    current: null,
    phase: "call",
    callStack: [],
    output: [],
    desc: `Ready. ${ORDER_LABEL[order]}: press Play.`,
  });

  const visit = (label: string) => {
    output.push(label);
    steps.push({
      current: null,
      phase: "call" as const,
      callStack: [...stack],
      output: [...output],
      desc: `Visit ${label}: append to output.`,
    });
  };

  const walk = (node: TNode | undefined): void => {
    if (!node) return;
    stack.push(node.key);
    steps.push({
      current: node.key,
      phase: "call",
      callStack: [...stack],
      output: [...output],
      desc: `Call ${node.label ?? node.key} (${ORDER_LABEL[order]}).`,
    });
    if (order === "pre") visit(node.label ?? node.key);
    walk(node.left);
    if (order === "in") visit(node.label ?? node.key);
    walk(node.right);
    if (order === "post") visit(node.label ?? node.key);
    stack.pop();
    steps.push({
      current: null,
      phase: "return",
      callStack: [...stack],
      output: [...output],
      desc: `Return from ${node.label ?? node.key}.`,
    });
  };

  walk(root);
  steps.push({
    current: null,
    phase: "done",
    callStack: [],
    output: [...output],
    desc: `Done. ${order}-order output: ${output.join(" ")}.`,
  });
  return steps;
}

/* ------------------------------------------------------------------ */
/* (b) Expression tree -> prefix / infix / postfix                      */
/* ------------------------------------------------------------------ */

export type NotationPhase = "prefix" | "infix" | "postfix";

export interface NotationStep {
  current: string | null;
  phase: NotationPhase;
  /** Tokens of the notation being built, in order. */
  output: string[];
  /** Keys of nodes already appended to the current notation's output. */
  visited: string[];
  desc: string;
}

const NOTATION_ORDER: Record<NotationPhase, TraversalOrder> = {
  prefix: "pre",
  infix: "in",
  postfix: "post",
};

/** Record all three notations of an expression tree, phase by phase.
 *  Steps carry node KEYS (labels can repeat, e.g. two "*" nodes). */
export function recordNotations(root: TNode): NotationStep[] {
  const steps: NotationStep[] = [];
  const phases: NotationPhase[] = ["prefix", "infix", "postfix"];
  for (const phase of phases) {
    // run the real traversal, but re-record with keys
    const output: string[] = [];
    const visited: string[] = [];
    const order = NOTATION_ORDER[phase];

    steps.push({
      current: null,
      phase,
      output: [],
      visited: [],
      desc:
        phase === "prefix"
          ? "Prefix: read every operator BEFORE its operands (pre-order)."
          : phase === "infix"
            ? "Infix: operator BETWEEN its operands (in-order)."
            : "Postfix: operator AFTER its operands (post-order).",
    });

    const walk = (node: TNode | undefined): void => {
      if (!node) return;
      const label = node.label ?? node.key;
      const append = () => {
        output.push(label);
        visited.push(node.key);
        steps.push({
          current: node.key,
          phase,
          output: [...output],
          visited: [...visited],
          desc: `Append ${label} to the ${phase} output: ${output.join(" ")}`,
        });
      };
      if (order === "pre") append();
      walk(node.left);
      if (order === "in") append();
      walk(node.right);
      if (order === "post") append();
    };
    walk(root);

    steps.push({
      current: null,
      phase,
      output: [...output],
      visited: [...visited],
      desc: `${phase} complete: ${output.join(" ")}`,
    });
  }
  return steps;
}

/* ------------------------------------------------------------------ */
/* (c) Postfix evaluation with an operand stack                         */
/* ------------------------------------------------------------------ */

export interface PostfixStep {
  /** Token being scanned (null = final state). */
  current: string | null;
  /** Stack contents, bottom to top. */
  stack: number[];
  /** During an operator step: [right, left] popped operands. */
  popped?: [number, number];
  /** Intermediate result just computed (operator steps). */
  result?: number;
  /** Tokens already consumed. */
  consumed: number;
  desc: string;
}

export class PostfixError extends Error {}

/** Tokenize "5 3 + 8 2 - *" into ["5","3","+","8","2","-","*"]. */
export function tokenizePostfix(expr: string): string[] {
  return expr
    .trim()
    .split(/\s+/)
    .filter((t) => t.length > 0);
}

const OPERATORS: Record<string, (a: number, b: number) => number> = {
  "+": (a, b) => a + b,
  "-": (a, b) => a - b,
  "*": (a, b) => a * b,
  "/": (a, b) => (b === 0 ? NaN : a / b),
};

/** Run the real stack algorithm and record each state. Throws PostfixError. */
export function recordPostfixEval(tokens: string[]): PostfixStep[] {
  const steps: PostfixStep[] = [];
  const stack: number[] = [];

  steps.push({
    current: null,
    stack: [],
    consumed: 0,
    desc: "Scan tokens left to right with one stack.",
  });

  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t in OPERATORS) {
      if (stack.length < 2) {
        throw new PostfixError(
          `Stack underflow at token "${t}" (step ${i + 1}): an operator needs two operands, but the stack holds ${stack.length}.`,
        );
      }
      const right = stack.pop()!; // FIRST pop = RIGHT operand
      const left = stack.pop()!;
      const result = OPERATORS[t](left, right);
      steps.push({
        current: t,
        stack: [...stack],
        popped: [right, left],
        consumed: i + 1,
        desc: `"${t}": pop ${right} (right), pop ${left} (left) → ${left} ${t} ${right} = ${result}. Push ${result}.`,
      });
      stack.push(result);
      steps.push({
        current: t,
        stack: [...stack],
        result,
        consumed: i + 1,
        desc: `Push ${result}. Stack: [${stack.join(", ")}].`,
      });
    } else {
      const n = Number(t);
      if (!Number.isFinite(n)) {
        throw new PostfixError(
          `"${t}" is not a number or a known operator (+ - * /).`,
        );
      }
      stack.push(n);
      steps.push({
        current: t,
        stack: [...stack],
        consumed: i + 1,
        desc: `"${t}" is an operand → push. Stack: [${stack.join(", ")}].`,
      });
    }
  }

  if (stack.length !== 1) {
    throw new PostfixError(
      `Invalid expression: ${stack.length} values left on the stack (expected exactly 1). Too many operands.`,
    );
  }
  steps.push({
    current: null,
    stack: [...stack],
    consumed: tokens.length,
    desc: `Done. The single value left on the stack is the answer: ${stack[0]}.`,
  });
  return steps;
}

/* ------------------------------------------------------------------ */
/* (d) Infix -> postfix (shunting-yard with operator stack)             */
/* ------------------------------------------------------------------ */

export interface InfixPostfixStep {
  current: string | null;
  /** Operator stack, bottom to top. */
  stack: string[];
  /** Output tokens accumulated so far. */
  output: string[];
  /** Number of tokens already consumed (including the current one). */
  consumed: number;
  desc: string;
}

const PREC: Record<string, number> = { "+": 1, "-": 1, "*": 2, "/": 2, "^": 3 };

/** Tokenize an infix expression: symbols, numbers, identifiers, parens. */
export function tokenizeInfix(expr: string): string[] {
  const out: string[] = [];
  const re = /(\d+\.?\d*|[A-Za-z]+|[+\-*/^()])/g;
  let m: RegExpExecArray | null;
  let consumed = 0;
  while ((m = re.exec(expr))) {
    if (m.index > consumed) {
      const skipped = expr.slice(consumed, m.index).trim();
      if (skipped) {
        throw new PostfixError(`Unexpected text "${skipped}" in the expression.`);
      }
    }
    consumed = m.index + m[0].length;
    out.push(m[0]);
  }
  const tail = expr.slice(consumed).trim();
  if (tail) throw new PostfixError(`Unexpected text "${tail}" in the expression.`);
  return out;
}

/** Run the real shunting-yard algorithm and record each state. */
export function recordInfixToPostfix(tokens: string[]): InfixPostfixStep[] {
  const steps: InfixPostfixStep[] = [];
  const stack: string[] = [];
  const output: string[] = [];

  steps.push({
    current: null,
    stack: [],
    output: [],
    consumed: 0,
    desc: "Scan the infix expression left to right.",
  });

  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t === "(") {
      stack.push(t);
      steps.push({
        current: t,
        stack: [...stack],
        output: [...output],
        consumed: i + 1,
        desc: `"(" → push onto the operator stack.`,
      });
    } else if (t === ")") {
      let foundParen = false;
      while (stack.length) {
        const top = stack[stack.length - 1];
        if (top === "(") {
          stack.pop();
          foundParen = true;
          break;
        }
        output.push(stack.pop()!);
      }
      if (!foundParen) throw new PostfixError('Unbalanced ")": no matching "(".');
      steps.push({
        current: t,
        stack: [...stack],
        output: [...output],
        consumed: i + 1,
        desc: `")" → pop to output until "(", discard both.`,
      });
    } else if (t in PREC) {
      const prec = PREC[t];
      const popped: string[] = [];
      while (
        stack.length &&
        stack[stack.length - 1] !== "(" &&
        (PREC[stack[stack.length - 1]] > prec ||
          (PREC[stack[stack.length - 1]] === prec && t !== "^"))
      ) {
        popped.push(stack.pop()!);
        output.push(popped[popped.length - 1]);
      }
      stack.push(t);
      steps.push({
        current: t,
        stack: [...stack],
        output: [...output],
        consumed: i + 1,
        desc:
          popped.length > 0
            ? `"${t}" (precedence ${prec}) → pop ${popped.join(", ")} (higher or equal), then push "${t}".`
            : `"${t}" (precedence ${prec}) → push onto the stack.`,
      });
    } else {
      output.push(t);
      steps.push({
        current: t,
        stack: [...stack],
        output: [...output],
        consumed: i + 1,
        desc: `"${t}" is an operand → straight to output.`,
      });
    }
  }

  while (stack.length) {
    const top = stack.pop()!;
    if (top === "(") throw new PostfixError('Unbalanced "(": never closed.');
    output.push(top);
  }
  steps.push({
    current: null,
    stack: [],
    output: [...output],
    consumed: tokens.length,
    desc: `End → pop everything. Postfix: ${output.join(" ")}`,
  });
  return steps;
}

/* ------------------------------------------------------------------ */
/* The chapter's example trees                                          */
/* ------------------------------------------------------------------ */

/**
 * ch08 "Bigger tree, full trace":
 *
 *         1
 *       /   \
 *      2     3
 *     / \   / \
 *    4   5 6   7
 *   / \
 *  8   9
 */
export const TRACE_TREE: TNode = {
  key: "1",
  left: {
    key: "2",
    left: { key: "4", left: { key: "8" }, right: { key: "9" } },
    right: { key: "5" },
  },
  right: { key: "3", left: { key: "6" }, right: { key: "7" } },
};

/**
 * ch08 expression tree for A/B*C*D+E  (correct structure — the original
 * figure had drawn D with A, B as children, which is not an expression
 * tree):
 *
 *          +
 *         / \
 *        *   E
 *       / \
 *      *   D
 *     / \
 *    /   C
 *   / \
 *  A   B
 */
export const EXPR_TREE: TNode = {
  key: "+",
  left: {
    key: "*1",
    label: "*",
    left: {
      key: "*2",
      label: "*",
      left: {
        key: "/",
        left: { key: "A" },
        right: { key: "B" },
      },
      right: { key: "C" },
    },
    right: { key: "D" },
  },
  right: { key: "E" },
};

/* ------------------------------------------------------------------ */
/* Rendering helper: TNode -> TreeGraph's nested node shape            */
/* ------------------------------------------------------------------ */

export function toGraphNode(n: TNode): TreeGraphNode {
  const children: TreeGraphNode[] = [];
  if (n.left) children.push({ ...toGraphNode(n.left), side: "left" as const });
  if (n.right)
    children.push({ ...toGraphNode(n.right), side: "right" as const });
  return {
    key: n.key,
    label: n.label ?? n.key,
    children: children.length ? children : undefined,
  };
}
